Object.assign(areaIntros,{"야마나시": ["YAMANASHI", "후지산과 호수, 계곡과 온천을 권역별로 나누어 여유롭게 둘러볼 수 있는 지역입니다."], "고후·쇼센쿄": ["KOFU · SHOSENKYO", "성터와 신사, 계곡 산책을 함께 즐길 수 있는 지역입니다. 시내와 산간 이동은 나누어 계획하세요."], "이사와·가쓰누마": ["ISAWA · KATSUNUMA", "과일과 온천, 포도밭 풍경을 함께 즐길 수 있는 지역입니다. 농원과 입욕 시설을 먼저 골라보세요."], "가와구치코·사이코": ["KAWAGUCHIKO · SAIKO", "호숫가 꽃길과 전통 마을을 함께 둘러볼 수 있는 지역입니다. 후지산이 보이지 않는 날의 선택지도 함께 준비하세요."], "후지요시다·오시노·야마나카코": ["FUJIYOSHIDA · OSHINO · YAMANAKAKO", "신사와 용천, 호수 풍경을 함께 즐길 수 있는 지역입니다. 세 지역 사이 이동에는 여유를 두세요."], "호쿠토·기요사토": ["HOKUTO · KIYOSATO", "고원 풍경과 남알프스 계곡을 즐길 수 있는 지역입니다. 고원과 계곡은 별도 일정으로 나누는 것을 권합니다."], "미노부": ["MINOBU", "사찰 참배와 산의 풍경을 천천히 즐기기 좋은 지역입니다."], "오쓰키": ["OTSUKI", "계곡 위 다리와 주변 풍경을 짧게 둘러보기 좋은 지역입니다."]});
